/*
 * A050207  Primes of the form p + (smallest prime >= p+1) + (smallest prime
 *          >= p+3) where p is a prime.
 * https://oeis.org/A050207
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = p + q + r, where p is the nth prime examined, q is the
 *            smallest prime ≥ p+1, r is the smallest prime ≥ p+3, and the sum
 *            p+q+r itself is prime. This is a searching definition – the
 *            sequence is generated by examining primes in increasing order
 * Range:     u8 n <= 9, u16 n <= 371, u32 n <= 372, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   is_prime, is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include "../utils/is_prime.h"          /* bool is_prime(idx_t)   */
#include "../utils/is_prime_big.h"      /* bool is_prime_big(seq_t)   */

static uint64_t next_prime_uint64(uint64_t start)
{
    for (uint64_t x = start; ; ++x) {
        if (is_prime(x))
            return x;
    }
}

/* returns the n-th term (1‑based) of the OEIS sequence A050207 */
seq_t a(idx_t n)
{
    if (n == 0)             /* sequence is defined for n≥1; return 0 for safety */
        return (seq_t)0;

    /* static cache of already generated terms                 */
    static seq_t *cache   = NULL;
    static size_t cache_len = 0;   /* number of elements stored          */
    static size_t cache_cap = 0;   /* allocated capacity                  */

    /* current prime being examined                           */
    static uint64_t current_p = 0; /* 0 indicates not yet initialized      */

    /* initialize cache on first use                          */
    if (cache == NULL) {
        cache_cap = 128;
        cache = (seq_t *)malloc(cache_cap * sizeof(seq_t));
    }

    /* initialize current_p on first use                       */
    if (current_p == 0)
        current_p = 2;

    /* generate terms until we have at least n terms            */
    while (cache_len < n) {
        uint64_t p  = current_p;                            /* prime p */
        uint64_t q1 = next_prime_uint64(p + 1);              /* smallest prime ≥ p+1 */
        uint64_t q2 = next_prime_uint64(p + 3);              /* smallest prime ≥ p+3 */

        seq_t sum = (seq_t)p + (seq_t)q1 + (seq_t)q2;

        if (is_prime_big(sum)) {
            if (cache_len == cache_cap) {                    /* grow cache */
                cache_cap *= 2;
                cache = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
            }
            cache[cache_len++] = sum;                        /* store term */
        }

        current_p = next_prime_uint64(current_p + 1);        /* next prime to examine */
    }

    return cache[n - 1];   /* convert 1‑based index to 0‑based array index */
}
